def date_to_epoch(date):
    return (date - datetime.datetime(1970,1,1)).total_seconds()

def parse_date(sdate):
    try:
        date = datetime.datetime.strptime(sdate, "%Y-%m-%dT%H:%M:%SZ")
        return date_to_epoch(date)
    except ValueError:
        return -1
    except:
        return -1


