def get_albums(aids):
    album_map, naids = get_items_from_cache(aids)
    max_per_batch = 20

    start = 0
    while start < len(naids):
        batch = naids[start:start + max_per_batch]
        results = _get_spotify().albums(batch)
        for album in results['albums']:
            falbum = flatten_album(album)
