def normalize_uri(uri):
    # convert urls like:
    #    https://open.spotify.com/user/plamere/playlist/3F1VlEt8oRsKOk9hlp5JDF
    #    https://open.spotify.com/track/0v2Ad5NPKP8LKv48m0pVHx
    #    https://open.spotify.com/album/0Gr8tHhOH8vzBTFqnf0YjT
    #    https://open.spotify.com/artist/6ISyfZw4EVt16zhmH2lvxp
    #    https://open.spotify.com/playlist/3F1VlEt8oRsKOk9hlp5JDF  (modern format)
    #
    # To URIs like:
    #    spotify:playlist:3F1VlEt8oRsKOk9hlp5JDF
    #    spotify:artist:6ISyfZw4EVt16zhmH2lvxp

    if uri:
        uri = uri.strip()
        if uri.startswith('https://open.spotify.com'):
            uri = uri.replace("https://open.spotify.com", "spotify")
            uri = uri.replace("/", ":")

        # Normalize old 5-part playlist URIs (spotify:user:X:playlist:Y) to 3-part
        parts = uri.split(':')
        if len(parts) == 5 and parts[0] == 'spotify' and parts[1] == 'user' and parts[3] == 'playlist':
            uri = 'spotify:playlist:' + parts[4]

    check_uri(uri)
    return uri

